scripts.continued_fraction:
def solve(inputs: dict) -> float:
    terms = inputs['TERMS']

    # Initialize p_prev and p with standard continued fraction values
    p_prev = 1      # p_{-1}
    p = terms[0]    # p_0 = a_0

    # Apply recurrence: p_n = a_n * p_{n-1} + p_{n-2}
    for i in range(1, len(terms)):
        p_new = terms[i] * p + p_prev
        p_prev = p
        p = p_new

    return float(p)

scripts.count_inversions:
def solve(inputs: dict) -> float:
    values = inputs['VALUES']

    count = 0
    # Check all pairs (i, j) where i < j
    for i in range(len(values)):
        for j in range(i + 1, len(values)):
            if values[i] > values[j]:
                count += 1

    return float(count)

scripts.find_gcd:
def solve(inputs: dict) -> float:
    import math

    values = inputs['VALUES']

    # Calculate GCD of all values in the list
    result = values[0]
    for i in range(1, len(values)):
        result = math.gcd(result, values[i])

    return float(result)

scripts.factorial_mod:
def solve(inputs: dict) -> float:
    n = inputs['N']
    mod = inputs['MOD']

    # Compute n! mod m
    result = 1
    for i in range(1, n + 1):
        result = (result * i) % mod

    return float(result)

scripts.sum_floor_division:
def solve(inputs: dict) -> float:
    A = inputs['A']
    B = inputs['B']

    # Compute sum of floor(A_i / B_i) for each position
    total = 0
    for i in range(len(A)):
        total += A[i] // B[i]

    return float(total)

